namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public string Id { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public string DepartmentName { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = string.Empty;
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICourseService
{
    IReadOnlyList<Department> GetDepartments();
    IReadOnlyList<Course> GetAllCourses();
    IReadOnlyList<Course> GetFeaturedCourses();
    IReadOnlyList<Course> SearchCourses(string? searchTerm, string? departmentId);
    Course? GetCourseById(string id);
    IReadOnlyList<Course> GetCoursesByDepartment(string departmentId);
    Department? GetDepartmentById(string id);
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class InMemoryCourseService : ICourseService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public InMemoryCourseService()
    {
        _departments =
        [
            new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and software systems." },
            new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = "hist", Name = "History", Description = "Exploration of past events, cultures, and civilizations." },
        ];

        _courses =
        [
            new()
            {
                Id = "CS101", Title = "Introduction to Programming",
                Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design. No prior experience required.",
                DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 3,
                Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Ada Lovelace",
                InstructorBio = "Dr. Lovelace has over 15 years of experience teaching introductory computer science and has published extensively on CS pedagogy.",
                IsFeatured = true
            },
            new()
            {
                Id = "CS201", Title = "Data Structures & Algorithms",
                Description = "Fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.",
                DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 4,
                Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Alan Turing",
                InstructorBio = "Dr. Turing specializes in algorithm complexity and has received multiple teaching awards.",
                IsFeatured = false
            },
            new()
            {
                Id = "CS310", Title = "Web Application Development",
                Description = "Build modern web applications using ASP.NET Core and Blazor. Covers server-side rendering, component architecture, and database integration.",
                DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 3,
                Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Grace Hopper",
                InstructorBio = "Dr. Hopper brings 10 years of industry experience building enterprise web applications before joining academia.",
                IsFeatured = true
            },
            new()
            {
                Id = "MATH101", Title = "Calculus I",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.",
                DepartmentId = "math", DepartmentName = "Mathematics", Credits = 4,
                Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Euclid Ramanujan",
                InstructorBio = "Dr. Ramanujan is a specialist in mathematical analysis and has authored three widely-used calculus textbooks.",
                IsFeatured = true
            },
            new()
            {
                Id = "MATH250", Title = "Linear Algebra",
                Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to data science.",
                DepartmentId = "math", DepartmentName = "Mathematics", Credits = 3,
                Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emmy Noether",
                InstructorBio = "Dr. Noether is recognized internationally for her contributions to abstract algebra and theoretical physics.",
                IsFeatured = false
            },
            new()
            {
                Id = "ENG110", Title = "Academic Writing",
                Description = "Develop critical thinking and writing skills through essay composition, research methods, and rhetorical analysis.",
                DepartmentId = "eng", DepartmentName = "English", Credits = 3,
                Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Prof. Virginia Woolf",
                InstructorBio = "Prof. Woolf has taught composition and rhetoric for 12 years and directs the university writing center.",
                IsFeatured = false
            },
            new()
            {
                Id = "ENG230", Title = "American Literature",
                Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, democracy, and social change.",
                DepartmentId = "eng", DepartmentName = "English", Credits = 3,
                Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. James Baldwin",
                InstructorBio = "Prof. Baldwin is an award-winning scholar of 20th-century American literature and cultural criticism.",
                IsFeatured = true
            },
            new()
            {
                Id = "PHYS201", Title = "Classical Mechanics",
                Description = "Newtonian mechanics, energy conservation, rotational dynamics, oscillations, and gravitational systems.",
                DepartmentId = "phys", DepartmentName = "Physics", Credits = 4,
                Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Richard Feynman",
                InstructorBio = "Dr. Feynman is renowned for making complex physics concepts accessible and engaging for undergraduates.",
                IsFeatured = false
            },
            new()
            {
                Id = "HIST101", Title = "World History to 1500",
                Description = "A global survey of civilizations, empires, and cultural exchange from prehistory through the late medieval period.",
                DepartmentId = "hist", DepartmentName = "History", Credits = 3,
                Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Dr. Howard Zinn",
                InstructorBio = "Dr. Zinn has spent two decades researching social movements and is known for his engaging lecture style.",
                IsFeatured = false
            },
            new()
            {
                Id = "HIST250", Title = "Modern European History",
                Description = "Europe from the Enlightenment to the present: revolutions, industrialization, world wars, and the European Union.",
                DepartmentId = "hist", DepartmentName = "History", Credits = 3,
                Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Mary Beard",
                InstructorBio = "Dr. Beard is a classicist and historian with a passion for connecting ancient and modern European traditions.",
                IsFeatured = false
            },
        ];
    }

    public IReadOnlyList<Department> GetDepartments() => _departments.AsReadOnly();

    public IReadOnlyList<Course> GetAllCourses() => _courses.AsReadOnly();

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, string? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Id.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList().AsReadOnly();
    }

    public Course? GetCourseById(string id) =>
        _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetCoursesByDepartment(string departmentId) =>
        _courses.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase))
                .ToList().AsReadOnly();

    public Department? GetDepartmentById(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        var course = GetCourseById(request.CourseId);
        return course is not null;
    }
}

