@using UniversityCourseCatalog.Models

<div class="card h-100 shadow-sm">
    <div class="card-body d-flex flex-column">
        <span class="badge bg-secondary mb-2 align-self-start">@Course.DepartmentName</span>
        <h5 class="card-title">@Course.Id — @Course.Title</h5>
        <p class="card-text text-muted flex-grow-1">@Truncate(Course.Description, 120)</p>
        <div class="d-flex justify-content-between align-items-center mt-2">
            <small class="text-body-secondary">@Course.Credits credits · @Course.InstructorName</small>
            <a href="courses/@Course.Id" class="btn btn-sm btn-outline-primary">Details</a>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = default!;

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "…");
}

@using UniversityCourseCatalog.Models

<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-3">
    @foreach (var dept in Departments)
    {
        <div class="col">
            <a href="courses?dept=@dept.Id" class="text-decoration-none">
                <div class="card border-primary h-100">
                    <div class="card-body">
                        <h5 class="card-title text-primary">@dept.Name</h5>
                        <p class="card-text text-muted">@dept.Description</p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public IReadOnlyList<Department> Departments { get; set; } = [];
}

@using UniversityCourseCatalog.Models

<div class="row g-3 mb-4">
    <div class="col-md-8">
        <input type="text"
               class="form-control"
               placeholder="Search courses by title, ID, or instructor…"
               @bind="SearchTerm"
               @bind:event="oninput"
               @bind:after="OnFilterChanged" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="SelectedDepartmentId" @bind:after="OnFilterChanged">
            <option value="">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
