@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject ICourseService CourseService
@rendermode InteractiveServer

<PageTitle>Browse Courses — University Course Catalog</PageTitle>

<h1 class="mb-4">Browse Courses</h1>

<CourseFilters Departments="_departments"
              SearchTerm="@_searchTerm"
              SelectedDepartmentId="@_selectedDepartmentId"
              OnFiltersChanged="HandleFiltersChanged" />

@if (_courses.Count == 0)
{
    <div class="alert alert-info">
        No courses match your search. Try adjusting your filters.
    </div>
}
else
{
    <p class="text-muted mb-3">Showing @_courses.Count course(s)</p>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in _courses)
        {
            <div class="col">
                <CourseCard Course="course" />
            </div>
        }
    </div>
}

@code {
    private IReadOnlyList<UniversityCourseCatalog.Models.Department> _departments = [];
    private IReadOnlyList<UniversityCourseCatalog.Models.Course> _courses = [];
    private string? _searchTerm;
    private string? _selectedDepartmentId;

    [SupplyParameterFromQuery(Name = "dept")]
    public string? DepartmentFilter { get; set; }

    protected override void OnInitialized()
    {
        _departments = CourseService.GetDepartments();
        _selectedDepartmentId = DepartmentFilter;
        _courses = CourseService.SearchCourses(_searchTerm, _selectedDepartmentId);
    }

    private void HandleFiltersChanged((string? SearchTerm, string? DepartmentId) filters)
    {
        _searchTerm = filters.SearchTerm;
        _selectedDepartmentId = filters.DepartmentId;
        _courses = CourseService.SearchCourses(_searchTerm, _selectedDepartmentId);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICourseService CourseService

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for
            <strong>@_selectedCourseTitle</strong> has been received.</p>
        <hr>
        <a href="courses" class="btn btn-outline-success">Browse More Courses</a>
        <a href="enroll" class="btn btn-success ms-2">Submit Another Request</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-7">
            <p class="text-muted mb-4">Fill out the form below to request enrollment in a course. All fields are required.</p>

            <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="EnrollmentForm" Enhance>
                <DataAnnotationsValidator />
                <AntiforgeryToken />
                <ValidationSummary class="text-danger mb-3" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
                    <ValidationMessage For="() => _model.StudentName" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" placeholder="e.g. STU-12345" />
                    <ValidationMessage For="() => _model.StudentId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="_model.CourseId">
                        <option value="">— Select a course —</option>
                        @foreach (var course in _courses)
                        {
                            <option value="@course.Id">@course.Id — @course.Title (@course.Credits cr)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => _model.CourseId" class="text-danger" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "course")]
    public string? PreselectedCourseId { get; set; }

    private IReadOnlyList<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        _courses = CourseService.GetAllCourses();

        if (!string.IsNullOrEmpty(PreselectedCourseId) && string.IsNullOrEmpty(_model.CourseId))
        {
            _model.CourseId = PreselectedCourseId;
        }
    }

    private void HandleSubmit()
    {
        var course = CourseService.GetCourseById(_model.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.Id} — {course.Title}" : _model.CourseId;

        if (CourseService.SubmitEnrollmentRequest(_model))
        {
            _submitted = true;
        }
    }
}

